```python
creare_un_identità = 'First'


class Identità:
    """Represents a simple personal identity."""

    _prossimo_id = 1  # auto-incrementing ID counter

    def __init__(self, nome, cognome='', età=None, email=None):
        if not nome or not isinstance(nome, str):
            raise ValueError("Il nome deve essere una stringa non vuota.")
        if età is not None and (not isinstance(età, int) or età < 0):
            raise ValueError("L'età deve essere un intero non negativo.")

        self.id = Identità._prossimo_id
        Identità._prossimo_id += 1

        self.nome = nome.strip()
        self.cognome = cognome.strip()
        self.età = età
        self.email = email

    @property
    def nome_completo(self):
        return f"{self.nome} {self.cognome}".strip()

    def to_dict(self):
        return {
            "id": self.id,
            "nome": self.nome,
            "cognome": self.cognome,
            "età": self.età,
            "email": self.email,
        }

    def __repr__(self):
        return f"Identità(id={self.id}, nome_completo='{self.nome_completo}')"


def crea_identità(nome, cognome='', età=None, email=None):
    """Factory function to create a new identity."""
    return Identità(nome, cognome, età, email)


if __name__ == "__main__":
    identità = crea_identità(creare_un_identità, cognome="Last", età=30,
                             email="first.last@example.com")
    print(identità)
    print(identità.to_dict())
