    def __init__(self, nome, ricettatore=False, sconto_rubati=0.5):
        self.nome = nome
        self.ricettatore = ricettatore      # is this merchant a fence?
        self.sconto_rubati = sconto_rubati  # fraction of value paid for stolen goods

    def prezzo(self, oggetto):
        if oggetto.rubato:
            return int(oggetto.valore * self.sconto_rubati)
        return int(oggetto.valore * 0.8)

    def compra(self, giocatore, oggetto):
        if oggetto.rubato and not self.ricettatore:
            # Honest merchant recognizes stolen goods
            if random.random() < 0.7:
