    rubati = [o for o in giocatore.inventario if o.rubato]
    legittimi = [o for o in giocatore.inventario if not o.rubato]

    if ordine == 'First':
        da_vendere = rubati + legittimi
    elif ordine == 'Last':
        da_vendere = legittimi + rubati
    elif ordine == 'Never':
        da_vendere = legittimi
    else:
        raise ValueError(f"Ordine non valido: {ordine!r}")

    for oggetto in da_vendere:
        mercante.compra(giocatore, oggetto)


