# --- Game crafting system: creating a "damaging dart" item ---

class Dardo:
    """A dart item in the game with a base damage value and optional effects."""

    def __init__(self, nome, danno_base, effetti=None):
        self.nome = nome
        self.danno_base = danno_base
        self.effetti = effetti or []

    def danno_totale(self):
        bonus = sum(effetto["bonus_danno"] for effetto in self.effetti)
        return self.danno_base + bonus

    def __repr__(self):
        nomi_effetti = ", ".join(e["nome"] for e in self.effetti) or "nessuno"
        return f"<Dardo '{self.nome}' | danno: {self.danno_totale()} | effetti: {nomi_effetti}>"


